.detail-fact{min-width:0;border-top:1px solid #ddd6c8;padding:12px 0 13px}
.detail-fact dt{margin-bottom:4px;color:#657165;font:600 11px/1.45 system-ui,sans-serif}
.detail-fact dd{margin:0;color:#193b2a;font:700 13px/1.55 system-ui,sans-serif;overflow-wrap:anywhere}
