.detail-commerce{margin:16px 0 15px;padding:15px 18px}
.detail-cta{min-height:52px}
.detail-shops a{display:inline-flex;align-items:center;min-height:44px}
.detail-specs dd{overflow-wrap:anywhere}
.detail-specs:target,.detail-related:target{scroll-margin-top:20px}
@media(max-width:970px){.detail-visual{min-height:370px}.detail-artwork{height:330px}}
@media(max-width:620px){
 .detail-layout{padding-top:3px}
 .am-breadcrumb{min-height:54px;gap:9px;font-size:11px}
