/* Atelier Montres: indexable editorial pages, no third-party fonts or scripts. */
:root{color-scheme:light;--ink:#183229;--accent:#a08350;--paper:#f8f5ec;--line:#dfd7c8}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--paper);color:var(--ink);font:16px/1.65 system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}
.wrap{width:min(1160px,calc(100% - 40px));margin-inline:auto}a{color:inherit;text-underline-offset:3px}a:focus-visible{outline:3px solid #b18c52;outline-offset:4px}.skip{position:absolute;top:-100px;left:14px;background:white;padding:10px;z-index:10}.skip:focus{top:10px}
.top{background:#172d25;color:#f8f2e5}.nav{min-height:78px;display:flex;align-items:center;justify-content:space-between;gap:20px}.logo{text-decoration:none;font:400 26px/1.2 Georgia,serif;white-space:nowrap}.nav nav{display:flex;gap:24px;flex-wrap:wrap}.nav nav a{font-size:14px;text-decoration:none}.nav nav a:hover{text-decoration:underline}
.crumb{font-size:13px;color:#57695b;padding:24px 0}.watch{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:clamp(24px,4vw,70px);align-items:center;padding:16px 0 64px}
.photo{min-height:350px;background:#f0ebe0;border:1px solid var(--line);display:grid;place-items:center;overflow:hidden}.photo img{width:100%;height:auto;max-height:560px;aspect-ratio:1;object-fit:contain}
