@media(max-width:780px){.seo-related-products{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:460px){.seo-related-products{grid-template-columns:1fr}.seo-related-photo{max-height:260px}}


/* Editorial method: transparent evidence and useful navigation. */
.seo-method-teaser{padding:65px 0;background:#192f27;color:#f7f2e8;border-top:1px solid #a79775}
.seo-method-teaser .eyebrow{color:#d9b980}
.seo-method-teaser h2{font:400 clamp(31px,4vw,46px)/1.15 Georgia,serif;max-width:760px;margin:16px 0}
.seo-method-teaser p:not(.eyebrow){max-width:740px;line-height:1.85;color:#e1e1d7}
.seo-method-teaser a{display:inline-flex;align-items:center;min-height:48px;color:#ffe3a7;font-weight:700;text-underline-offset:5px}
.seo-method{padding-bottom:22px}
.seo-method>.lead{max-width:880px}
.seo-method-credit{color:#5e6a5e;font-size:13px;line-height:1.8}
.seo-method-stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:30px 0 14px}
.seo-method-stats>div{display:flex;flex-direction:column;gap:7px;border:1px solid #dfd7c8;background:#fffdfa;padding:21px}
.seo-method-stats strong{font:400 clamp(30px,4vw,45px)/1 Georgia,serif;color:#1b4832}
.seo-method-stats span{font-size:12px;line-height:1.45;color:#627163}
.seo-method .content{padding-top:0}
.seo-method-brands{display:flex;flex-wrap:wrap;list-style:none;gap:9px;padding:0;margin:16px 0}
.seo-method-brands li{padding:6px 11px;background:#eae7dd;border:1px solid #ded4c1;font-size:13px}
.seo-method-steps{padding-left:24px;display:grid;gap:12px;line-height:1.7;color:#425c4a}
.seo-method-products li{font-size:14px}
@media(max-width:720px){.seo-method-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.seo-method-teaser{padding:46px 0}.seo-method-stats>div{padding:16px}}

/* Model-specific static product pages — same factual overview as the live
   interactive catalogue; no synthetic pictures, availability or review data. */
.watch-product{grid-template-columns:minmax(0,.94fr) minmax(0,1.06fr);gap:clamp(24px,4.5vw,62px);align-items:center;padding:13px 0 30px}
.watch-product .watch-photo{display:flex;flex-direction:column;align-items:stretch;justify-content:center;position:relative;min-width:0;min-height:520px;background:radial-gradient(ellipse at 48% 37%,#fffefa 0%,#eef0e9 61%,#e0e8de 100%);border:1px solid #d9dfd4;box-shadow:0 24px 55px #1635230e;padding:22px;isolation:isolate}
.watch-product .watch-photo::before{content:'';position:absolute;inset:16px;border:1px solid #ffffffb3;pointer-events:none}
.watch-product .watch-photo img{display:block;width:100%;height:auto;max-height:490px;aspect-ratio:auto;object-fit:contain;filter:drop-shadow(0 17px 15px #1b362625);mix-blend-mode:multiply}
.watch-product .watch-photo .watch-vector{min-height:350px}
.watch-photo-caption{display:flex;justify-content:space-between;align-items:center;gap:10px;border-top:1px solid #d7dcd2;margin-top:13px;padding:11px 0 0;color:#5b6b5d;font:700 10px/1.5 system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase}
.watch-photo-caption span:first-child{color:#947954;white-space:nowrap}
.watch-photo-caption span:last-child{text-align:right}
.watch-product .intro{min-width:0}
.watch-product .intro h1{font-size:clamp(34px,4.2vw,60px);letter-spacing:-.037em;overflow-wrap:anywhere;margin:12px 0 17px}
.watch-product .intro .subtitle{font-size:clamp(18px,2.2vw,25px);line-height:1.42;margin:0 0 12px}
.watch-product .intro .lead{font-size:15px;line-height:1.8;margin:0 0 19px}
.watch-facts{padding:18px 20px 12px;background:#f0ede5;border:1px solid #ded4c4}
.watch-facts-caption{margin:0 0 11px!important;color:#826b49!important;font:750 10px/1.4 system-ui,sans-serif!important;letter-spacing:.13em}
.watch-facts dl{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 15px;margin:0}
.watch-quickfact{min-width:0;padding:11px 0 12px;border-top:1px solid #dcd4c7}
.watch-quickfact dt{margin-bottom:4px;font:600 11px/1.45 system-ui,sans-serif;color:#687666}
.watch-quickfact dd{margin:0;font:700 13px/1.55 system-ui,sans-serif;color:#203d2c;overflow-wrap:anywhere}
.watch-quickfact .watch-fact-unknown{font-weight:500;color:#797a70}
.watch-product .tags{margin:16px 0;gap:6px}
.watch-product .tags span{font-size:11px;padding:6px 9px}
.watch-product .disclosure{font-size:12px;margin:15px 0}
.watch-actions{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.watch-actions .primary,.watch-actions .secondary{display:flex;align-items:center;justify-content:center;min-height:48px;padding:12px 15px;margin:0;font-size:12px;line-height:1.5}
.watch-actions .primary{grid-column:1/-1}
.watch-actions .secondary{border-color:#b4c1b4;background:#fdfcf7}
.watch-section-nav{display:flex;align-items:center;gap:8px;overflow-x:auto;padding:4px 0 24px;scrollbar-color:#b7a180 #f0ece4;scrollbar-width:thin;scroll-snap-type:x proximity}
.watch-section-nav a{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;white-space:nowrap;min-height:44px;padding:10px 15px;background:#eee8dc;border:1px solid #d7c9b2;color:#2a4c37;font:700 12px/1.4 system-ui,sans-serif;scroll-snap-align:start}
.watch-section-nav a:hover{background:#e3dbc9}
.watch-section-nav a:focus-visible{outline:3px solid #b18c52;outline-offset:2px}
.watch-section-nav+.content{padding-top:0}
.watch-section-nav+.content h2[id]{scroll-margin-top:25px}
@media(max-width:800px){.watch-product{grid-template-columns:1fr;gap:22px}.watch-product .watch-photo{min-height:350px}.watch-product .watch-photo img{max-height:390px}.watch-product .intro .lead{font-size:14px}.watch-product .intro h1{font-size:clamp(34px,7vw,50px)}}
@media(max-width:480px){
 .watch-product{padding:0 0 13px}
 .watch-product .watch-photo{min-height:280px;padding:12px}
 .watch-product .watch-photo::before{inset:8px}
 .watch-product .watch-photo img{max-height:320px}
 .watch-photo-caption{font-size:9px;gap:5px;margin-top:7px}
 .watch-product .intro h1{font-size:clamp(32px,8.7vw,42px)}
 .watch-facts{padding:13px 14px 10px}
 .watch-facts dl{gap:0 10px}
 .watch-quickfact dd{font-size:12px}
 .watch-actions{grid-template-columns:1fr}
 .watch-actions .primary{grid-column:auto}
 .watch-section-nav{margin-right:-14px;padding-right:14px}
}

'use strict';
/* Editorial vector watch images for product SEO pages. Never loads remote images. */
(() => {
  const nodes=document.querySelectorAll('.watch-vector[data-watch-id]');
  for(const mount of nodes){
    const {watchId:id,brand,model,tone}=mount.dataset;
    if(!/^[a-z0-9-]{4,64}$/.test(id||'')||!brand||!model)continue;
    // The original SVG renderer constructs DOM nodes without innerHTML and
    // clearly labels its work as an illustration rather than product photography.
    window.AtelierWatch?.render(mount,{id,brand,model,tone});
  }
})();

'use strict';
(() => {
  const $=(x)=>document.getElementById(x);
  const cards=$('studioResults'), status=$('studioStatus'), count=$('studioCount'),summary=$('studioSummary'),copy=$('studioCopy'),copyStatus=$('studioCopyStatus'),empty=$('studioEmpty'),form=$('studioCalc'),unit=$('studioUnitCost'),budget=$('studioBudgetStatus');
  if(!cards||!status||!count||!summary||!copy||!form||!unit||!budget)return;
  let candidates=[],selected=new Set(),active='all';
  const KEY='atelier-sourcing-shortlist-v1';
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(saved))selected=new Set(saved.filter(x=>typeof x==='string'))}catch(_){ }
  const node=(tag,cls,value)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(value!==undefined)el.textContent=value;return el};
  const money=(v,c)=>{try{return new Intl.NumberFormat('fr-FR',{style:'currency',currency:c,maximumFractionDigits:2}).format(v)}catch(_){return String(v)+' '+c}};
  const accepted=new Set(['classic','sport','minimal']);
  const valid=(x)=>x&&x.status==='research_only'&&typeof x.id==='string'&&accepted.has(x.family)&&typeof x.supplier==='string'&&typeof x.model==='string'&&Number.isFinite(x.price?.from)&&Number.isFinite(x.price?.to)&&x.price.to>=x.price.from&&['EUR','USD'].includes(x.price.currency)&&Number.isInteger(x.minimumOrderQuantity)&&x.minimumOrderQuantity>0&&Array.isArray(x.issues)&&x.issues.length>=2&&typeof x.sourceUrl==='string'&&x.sourceUrl.startsWith('https://');
  function render() {
    const visible=candidates.filter(c=>active==='all'||(active==='shortlist'?selected.has(c.id):c.family===active));
    cards.replaceChildren(...visible.map(c=>{
      const box=node('article','studio-card');
      box.append(node('span','studio-card-flag','À vérifier — ne pas commander sans devis'));
      box.append(node('h3','',c.supplier));
      box.append(node('p','studio-model',c.model));
      const price=node('p','studio-price',money(c.price.from,c.price.currency)+' – '+money(c.price.to,c.price.currency));
      price.append(node('small','','Tarifs d’annonce, hors importation et livraison'));
      box.append(price);
      const dl=node('dl');
      for(const [name,value] of [['Commande minimale',c.minimumOrderQuantity+' pièce'+(c.minimumOrderQuantity>1?'s':'')],['Marque propre',c.branding]]) {
        const wrap=node('div');wrap.append(node('dt','',name),node('dd','',value));dl.append(wrap);
      }
      box.append(dl);
      const issues=node('div','studio-issues');issues.append(node('strong','','À obtenir avant validation'));
      const ul=node('ul');
      for(const issue of c.issues.slice(0,5))ul.append(node('li','',issue));
      issues.append(ul);box.append(issues);
      const actions=node('div','studio-card-actions');
      const link=node('a','','Voir la fiche fournisseur');
      link.href=c.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';link.title='Ouvrir l’annonce sur le site du fournisseur';
      const button=node('button','',selected.has(c.id)?'✓ Retirer de la liste':'Ajouter à la shortlist');
      button.type='button';button.setAttribute('aria-pressed',String(selected.has(c.id)));
      button.addEventListener('click',()=>{
        selected.has(c.id)?selected.delete(c.id):selected.add(c.id);
        try{localStorage.setItem(KEY,JSON.stringify([...selected]))}catch(_){}
        copyStatus.textContent='';render();
      });
      actions.append(link,button);box.append(actions);
      return box;
    }));
    empty.hidden=visible.length!==0;
    count.textContent=String(selected.size);
    const chosen=candidates.filter(c=>selected.has(c.id));
    summary.textContent=chosen.length?chosen.map(c=>c.supplier).join(' · '):'Sélectionnez des fournisseurs à consulter.';
    status.textContent=visible.length+' offre'+(visible.length>1?'s':'')+' étudiée'+(visible.length>1?'s':'');
    copy.disabled=chosen.length===0;
    document.querySelectorAll('.studio-filters button').forEach(b=>{const yes=b.dataset.filter===active;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});
  }
  document.querySelectorAll('.studio-filters button').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;render()}));
  copy.addEventListener('click',async()=>{
    const list=candidates.filter(c=>selected.has(c.id));
    if(!list.length)return;
    const txt='Fournisseurs Atelier Montres — vérifications nécessaires\n'+list.map(c=>'- '+c.supplier+' | '+c.model+' | '+c.sourceUrl).join('\n');
    try{await navigator.clipboard.writeText(txt);copyStatus.textContent='Shortlist copiée.'}catch(_){copyStatus.textContent='Copie impossible sur cet appareil : '+list.map(c=>c.supplier).join(', ')}
  });
  const currency=(x)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(x);
  function calculate(){
    const values=Object.fromEntries(new FormData(form).entries());
    const quantity=Number(values.quantity),price=Number(values.unitPrice),shipping=Number(values.freight),taxes=Number(values.taxes),extras=Number(values.extras);
    if(!Number.isSafeInteger(quantity)||quantity<1||quantity>1000||![price,shipping,taxes,extras].every(v=>Number.isFinite(v)&&v>=0&&v<=1e5)){
      unit.textContent='—';budget.textContent='Corrigez les montants et la quantité.';return;
    }
    const total=price*quantity+shipping+taxes+extras;
    const landed=total/quantity;
    unit.textContent=currency(landed);
    budget.textContent=(landed<=20?'Dans l’objectif de 20 €':'Au-dessus de l’objectif de 20 €')+' • Total du lot : '+currency(total)+'. Estimation, non devis.';
  }
  form.addEventListener('input',calculate);calculate();
  fetch('./fournisseurs.json',{cache:'no-store'})
    .then(r=>{if(!r.ok)throw Error('feed');return r.json()})
    .then(data=>{
      if(data?.version!==1||!Array.isArray(data.candidates))throw Error('schema');
      candidates=data.candidates.filter(valid);
      selected=new Set([...selected].filter(id=>candidates.some(c=>c.id===id)));
      render();
    })
    .catch(()=>{status.textContent='Données fournisseurs indisponibles.';empty.hidden=false});
})();

'use strict';
/* Handcrafted vector drawings, not official product photography. No third-party image rights needed. */
(() => {
  const NS='http://www.w3.org/2000/svg';
  const colors={turquoise:['#ade8dc','#4d8d94'],blue:['#bdd5e8','#285474'],green:['#7eba9c','#185a41'],black:['#6c8075','#142522'],ivory:['#fbf5e5','#beb49b'],silver:['#e5e9e2','#879b91'],transparent:['#d8f1ea','#88b9b3']};
  const types={
   'casio-a168wa':'digital','casio-mtp-b145':'square','casio-mtp-1302':'date',
   'casio-mdv107':'diver','casio-ltp1302':'date-small','swatch-clearly':'transparent',
   'citizen-eco':'eco','citizen-openheart':'openheart','citizen-tsuyosa':'integrated',
   'orient-bambino':'leather','seiko-5':'diver','tissot-prx-quartz':'integrated',
   'tissot-prx-auto':'textured','hamilton-khaki':'field','seiko-sharp':'textured'
  };
  function el(tag,attrs,txt){
   const e=document.createElementNS(NS,tag);
   for(const [k,v] of Object.entries(attrs||{})) if(v!==null&&v!==undefined)e.setAttribute(k,String(v));
   if(txt!==undefined)e.textContent=String(txt);
   return e;
  }
  function put(parent,tag,attrs,txt){const child=el(tag,attrs,txt);parent.appendChild(child);return child;}
  function render(mount,p,compact){
   if(!mount||!p)return;
   const id=String(p.id||'dial').replace(/[^a-z0-9-]/gi,'').slice(0,64);
   const type=types[id]||'date';
   const tone=colors[p.tone]||colors.green;
   const svg=el('svg',{xmlns:NS,viewBox:'0 0 340 380',role:'img',focusable:'false','aria-label':'Interprétation vectorielle du style '+p.brand+' '+p.model+', différente de la photo réelle',class:'am-watch-svg'});
   const defs=put(svg,'defs');
   let g=put(defs,'linearGradient',{id:'steel-'+id,x1:'0%',y1:'0%',x2:'100%',y2:'30%'});
   for(const [offset,color] of [['0%','#495c53'],['24%','#ecefe8'],['50%','#7f9188'],['74%','#ecede4'],['100%','#62756b']])put(g,'stop',{offset,'stop-color':color});
   g=put(defs,'radialGradient',{id:'face-'+id,cx:'30%',cy:'22%',r:'87%'});
   put(g,'stop',{offset:'0%','stop-color':tone[0]});put(g,'stop',{offset:'100%','stop-color':tone[1]});
   put(svg,'ellipse',{cx:174,cy:348,rx:75,ry:13,fill:'#18261c',opacity:'.11'});
   const body=put(svg,'g',{transform:'rotate(-13 170 186)'});
   const metal='url(#steel-'+id+')';
   const face='url(#face-'+id+')';
   const darkStrap=type==='leather'||type==='diver'&&id==='casio-mdv107';
   const strap=type==='transparent'?'#e1f1ecaa':darkStrap?'#353c35':metal;
   for(const y of [13,230])put(body,'rect',{x:124,y,width:92,height:136,rx:darkStrap?18:9,fill:strap,stroke:'#82948b','stroke-width':1.5});
   if(!darkStrap&&type!=='transparent')for(const yBase of [24,240])for(let i=0;i<6;i++)put(body,'line',{x1:127,y1:yBase+i*18,x2:213,y2:yBase+i*18,stroke:'#6f8479','stroke-width':1.2,opacity:'.72'});
   if(type==='integrated'||type==='textured')put(body,'path',{d:'M125 139 L133 102 L207 102 L216 140 L216 225 L204 255 L134 255 L123 220Z',fill:metal,stroke:'#84958a','stroke-width':2});
   const square=type==='digital'||type==='square';
   const cx=170,cy=184;
   if(square){
     put(body,'rect',{x:98,y:112,width:144,height:147,rx:type==='digital'?15:25,fill:metal,stroke:'#a0a594','stroke-width':2.5});
     put(body,'rect',{x:110,y:125,width:120,height:121,rx:9,fill:type==='digital'?'#243b36':face,stroke:'#556f60','stroke-width':3});
     if(type==='digital'){
       put(body,'rect',{x:120,y:157,width:100,height:57,rx:4,fill:'#c3d2b6',stroke:'#253d30','stroke-width':1});
       put(body,'text',{x:170,y:185,'text-anchor':'middle','font-family':'monospace','font-size':28,'font-weight':700,fill:'#17352a'},'10:28');
       put(body,'text',{x:170,y:141,'text-anchor':'middle','font-family':'system-ui','font-size':10,fill:'#d0d4c3'},'DIGITAL');
       put(body,'text',{x:170,y:233,'text-anchor':'middle','font-family':'system-ui','font-size':8,fill:'#d0d4c3'},'ILLUSTRATION');
     } else {
       for(let i=0;i<12;i++){const a=i*Math.PI/6;put(body,'line',{x1:cx+41*Math.sin(a),y1:cy-41*Math.cos(a),x2:cx+48*Math.sin(a),y2:cy-48*Math.cos(a),stroke:'#f7eccd','stroke-width':i%3===0?3:1.5});}
     }
   } else {
     if(type==='diver'){put(body,'circle',{cx,cy,r:89,fill:'#23382e',stroke:'#a9b1a4','stroke-width':11});for(let i=0;i<12;i++){const a=i*Math.PI/6;put(body,'circle',{cx:cx+84*Math.sin(a),cy:cy-84*Math.cos(a),r:i%3===0?2.5:1.1,fill:'#eee9cd'});}}
     else put(body,'circle',{cx,cy,r:88,fill:metal,stroke:'#7c806e','stroke-width':3});
     put(body,'circle',{cx,cy,r:type==='diver'?71:77,fill:face,stroke:type==='transparent'?'#a4c7ba':'#ecdfc0','stroke-width':2});
     if(type==='textured')for(let y=123;y<249;y+=11)for(let x=110;x<231;x+=11)if(Math.hypot(x-cx,y-cy)<67)put(body,'rect',{x,y,width:7,height:7,fill:'#e3f0df',opacity:'.13'});
     if(type==='field')for(let i=1;i<=12;i++){const a=i*Math.PI/6;put(body,'text',{x:cx+54*Math.sin(a),y:cy-54*Math.cos(a)+4,'text-anchor':'middle','font-family':'system-ui','font-size':10,'font-weight':700,fill:'#f3e7cc'},i);}
     else for(let i=0;i<12;i++){const a=i*Math.PI/6;put(body,'line',{x1:cx+59*Math.sin(a),y1:cy-59*Math.cos(a),x2:cx+66*Math.sin(a),y2:cy-66*Math.cos(a),stroke:p.tone==='ivory'?'#625f53':'#f2e9d3','stroke-width':i%3===0?4:2,'stroke-linecap':'round'});}
     if(type==='openheart'){put(body,'circle',{cx:176,cy:211,r:18,fill:'#3a4235',stroke:'#e2c58a','stroke-width':3});put(body,'circle',{cx:176,cy:211,r:9,fill:'#d0ba83'});}
     if(['date','date-small','eco','integrated','textured','field','diver'].includes(type)){put(body,'rect',{x:204,y:176,width:21,height:17,rx:2,fill:'#eadfc6'});put(body,'text',{x:214,y:188,'text-anchor':'middle','font-size':10,'font-family':'system-ui',fill:'#203529','font-weight':700},'26');}
   }
   if(type!=='digital'){
     const handColor=p.tone==='ivory'?'#615b4d':'#fff1d4';
     put(body,'line',{x1:cx,y1:cy,x2:151,y2:146,stroke:handColor,'stroke-width':5,'stroke-linecap':'round'});
     put(body,'line',{x1:cx,y1:cy,x2:211,y2:198,stroke:handColor,'stroke-width':3,'stroke-linecap':'round'});
     put(body,'line',{x1:cx,y1:cy,x2:183,y2:121,stroke:'#c88e6d','stroke-width':1.5});
     put(body,'circle',{cx,cy,r:5,fill:'#e8c893'});
   }
   put(body,'rect',{x:254,y:177,width:11,height:21,rx:3,fill:'#b4a27a',stroke:'#4e564b','stroke-width':1});
   mount.replaceChildren(svg);
   return svg;
  }
  window.AtelierWatch=Object.freeze({render});
})();
